'use client'

import { PRODUCT_CATEGORIES, PRODUCT_STATUS_LABELS, type ProductListQuery, type ProductStatus } from '@/lib/vendor/catalog'

interface Props { query: ProductListQuery; onChange: (query: ProductListQuery) => void }
export function ProductSearchBar({ query, onChange }: Props) { return <div className="catalog-filter-bar"><label className="catalog-search"><span>Search catalog</span><input value={query.search ?? ''} onChange={(event) => onChange({ ...query, search: event.target.value, page: 1 })} placeholder="Search by name, SKU or category" /></label><label><span>Status</span><select value={query.status ?? 'all'} onChange={(event) => onChange({ ...query, status: event.target.value as ProductStatus | 'all', page: 1 })}><option value="all">All statuses</option>{Object.entries(PRODUCT_STATUS_LABELS).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label><label><span>Category</span><select value={query.category ?? 'all'} onChange={(event) => onChange({ ...query, category: event.target.value, page: 1 })}><option value="all">All categories</option>{PRODUCT_CATEGORIES.map((category) => <option value={category} key={category}>{category}</option>)}</select></label><label><span>Sort</span><select value={query.sort ?? 'updated_desc'} onChange={(event) => onChange({ ...query, sort: event.target.value as ProductListQuery['sort'], page: 1 })}><option value="updated_desc">Recently updated</option><option value="name_asc">Name A-Z</option><option value="price_asc">Price low-high</option><option value="price_desc">Price high-low</option></select></label></div> }